  "contradictory_card_ids": ["C16", "C19", "C20"],
  "prediction_basis_card_ids": ["C18", "C12", "C01", "C05", "C08"],
  "claims": [
    {
      "claim": "C18 reports an absolute oral bioavailability (Fpod) of 10% for compound 4p in cynomolgus monkeys, which is below the 20% threshold; if compound 4p corresponds to the query, this is direct low-F evidence.",
      "card_ids": ["C18"]
    },
    {
      "claim": "C12 reports an estimated absolute oral bioavailability of 3% in humans for astemizole, a lipophilic piperidine-containing molecule; the query shares a lipophilic, neutral, heteroaromatic piperidine scaffold and an unfavorable solubility prior.",
      "card_ids": ["C12"]
    },
    {
      "claim": "C01 and C05 report low/poor oral bioavailability for FK3453 in humans, attributed to metabolism-mediated clearance that was not predicted preclinically; this supports that lipophilic heteroaromatic scaffolds can have F well below 20% even when permeability is not the limiting factor.",
      "card_ids": ["C01", "C05"]
    },
    {
      "claim": "C08 reports poor oral bioavailability for danavorexton, requiring IV administration in clinical studies; this provides additional transferable evidence that a lipophilic small-molecule amide/sulfonamide scaffold can have F < 20% due to first-pass or metabolic loss.",
      "card_ids": ["C08"]
    },
    {
      "claim": "C22 and C26 report low absolute oral bioavailability in rats for DX-9065 (10.8%) and olcegepant (<1%), respectively, supporting low F for structurally diverse low-solubility molecules.",
      "card_ids": ["C22", "C26"]
    },
    {
      "claim": "C16 and C19 report high absolute oral bioavailability for FK3453 in dogs (71.3%-93.4%), but this is species-specific and does not override the human low-F evidence for FK3453 or the direct low-F monkey value for compound 4p.",
      "card_ids": ["C16", "C19"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C18", "C22", "C26", "C28", "C21", "C23", "C17"]
    }
  ],
  "evidence_gaps": [
    "No human absolute oral bioavailability measurement for the query is provided.",
    "C18 reports Fpod for compound 4p in monkeys; the card does not explicitly identify the query, so direct applicability is inferred rather than confirmed.",
    "No IV comparator or matched oral-versus-IV exposure data for the query in humans are available.",
    "Solubility and first-pass metabolism of the query are not directly measured; the prior only indicates unfavorable solubility and mixed/unclear metabolism.",
    "Species differences in F (e.g., FK3453 high in dogs but low in humans) limit extrapolation from animal data."
  ],
  "decision_summary": "The query is a lipophilic, neutral, heteroaromatic piperidine acrylamide. Direct monkey Fpod of 10% for compound 4p (C18), if applicable, is below the 20% threshold. Transferable low-F contexts (C12, C01/C05, C08) and additional low-F animal/human records (C22, C26, C28) support an affirmative low prediction. High-F dog data for FK3453 (C16/C19) are species-specific and do not overturn the low direction. Prediction: low."
}

